/// C-compatible packet header.
///
/// `#[repr(C)]` guarantees the layout matches
/// `struct PacketHeader { uint8_t tag; uint32_t len; uint16_t flags; }`
/// on every target: field offsets 0, 4, 8; size 12 bytes; alignment 4.
#[repr(C)]
pub struct PacketHeader {
    pub tag: u8,
    pub len: u32,
    pub flags: u16,
}

/// Returns the size of a `PacketHeader` in bytes (12).
#[no_mangle]
pub extern "C" fn packet_header_size() -> usize {
    std::mem::size_of::<PacketHeader>()
}
```

Note: `#[repr(C)]` is what makes the layout identical to the C struct on every target — it forces fields to be laid out in declaration order with C-style alignment and padding (no extra padding beyond what C would produce, since the natural alignment here already coincides, but the attribute is the portable guarantee).

